package com.rubidiumclient.module.combatimport com.rubidiumclient.core.proxy.EntityTrackerimport com.rubidiumclient.core.relay.RubidiumRelaySessionimport com.rubidiumclient.events.PacketEventimport com.rubidiumclient.events.PacketEventBusimport com.rubidiumclient.module.*import com.rubidiumclient.utils.MathUtilimport com.rubidiumclient.utils.PacketUtilimport com.rubidiumclient.utils.PlacementUtilimport com.rubidiumclient.utils.WorldBlockTrackerimport kotlinx.coroutines.*import org.cloudburstmc.math.vector.Vector3iimport org.cloudburstmc.protocol.bedrock.data.LevelEventimport org.cloudburstmc.protocol.bedrock.packet.*import kotlin.math.floor/** * CrystalAura — PlacementUtil tabanlı sürüm. * * KÖK NEDEN (önceki sürümde neden hiç kristal yerleşmiyordu): *   Bu modül kendi private blockDefCache + ensureBlockCacheWarmed() fonksiyonlarını *   kullanıyordu. Bu fonksiyon block definition'ların SimpleBlockDefinition VEYA *   reflection ile "identifier" field/getIdentifier() olduğunu varsayıyordu. *   Ama hashed-block-id sunucularında (çoğu modern Bedrock sürümü) definition'lar *   Definitions.NbtBlockDefinitionRegistry.NbtBlockDefinition tipinde geliyor — *   identifier bunlarda def.tag.getString("name") ile okunuyor, ne bir field ne *   bir method. Reflection bunu asla bulamıyordu, cache SONSUZA KADAR boş kalıyordu, *   dolayısıyla sendPlacementUseRaw() hep false dönüyordu (kristal hiç yerleşmiyordu) *   VE her tick 20.000 blokluk tarama tekrar tekrar çalışıyordu (gereksiz CPU yükü). * *   PlacementUtil.getBlockDefinition() bu iki tipi de doğru işliyor (bkz. *   PlacementUtil.kt satır 179-183) — bu modül artık kendi kopyasını tutmuyor, *   doğrudan PlacementUtil'i kullanıyor. */class CrystalAura : BaseModule(    name        = "CrystalAura",    category    = ModuleCategory.COMBAT,    description = "Hasar simülasyonuna göre en iyi noktaya kristal yerleştirir/kırar") {    companion object {        private const val EXPLOSION_SIZE   = 6f        private const val TICK_INTERVAL_MS = 50L        private const val CRYSTAL_ID       = "minecraft:end_crystal"        private const val LOG_FAIL_INTERVAL_MS = 1000L        private val NON_SOLID = setOf(            "minecraft:air", "minecraft:water", "minecraft:flowing_water",            "minecraft:lava", "minecraft:flowing_lava",            "minecraft:void_air", "minecraft:cave_air"        )    }    // ── Ayarlar ──────────────────────────────────────────────────────────    private val range           = float("Range",           5f,   3f,  10f)    private val suicide         = bool ("Suicide",         false)    private val place           = bool ("Place",           true)    private val placeCount      = int  ("PlaceCount",      4,    1,   8)    private val placeDelayMs    = int  ("PlaceDelay",      100,  50,  500)    private val explodeDelayMs  = int  ("ExplodeDelay",    50,   20,  300)    private val removeParticles = bool ("RemoveParticles", true)    private val shortcut        = bool ("Shortcut",        false)    private val log             = bool ("Log",             false)    // ── State ─────────────────────────────────────────────────────────────    @Volatile private var lastExplodeMs = 0L    @Volatile private var lastPlaceMs   = 0L    @Volatile private var lastFailLogMs = 0L    private var tickJob: Job? = null    private data class ExplosionResult(val mostDamage: Float, val selfDamage: Float)    // ── Lifecycle ─────────────────────────────────────────────────────────    override fun onEnable() {        super.onEnable()        lastExplodeMs = 0L        lastPlaceMs   = 0L        PacketEventBus.register(this)        tickJob = scope.launch { tickLoop() }    }    override fun onDisable() {        tickJob?.cancel()        PacketEventBus.unregister(this)        super.onDisable()    }    // ── Packet handler ────────────────────────────────────────────────────    override fun onPacket(event: PacketEvent) {        if (!isEnabled) return        when (val pkt = event.packet) {            // Yeni doğan kristali anında patlat (tick bekleme olmadan).            is AddEntityPacket -> {                if (!pkt.identifier.contains("crystal", ignoreCase = true)) return                val now = System.currentTimeMillis()                if (now - lastExplodeMs < explodeDelayMs.value) return                val cx = pkt.position.x; val cy = pkt.position.y; val cz = pkt.position.z                if (MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ) > range.value) return                val dmg = simulateExplosionDamage(cx, cy, cz)                if (dmg.selfDamage <= dmg.mostDamage || suicide.value) {                    val session = PacketEventBus.currentSession ?: return                    explodeCrystal(session, pkt.runtimeEntityId)                    lastExplodeMs = now                    sendLog(session, "Patlatıldı (anlık) - ${dmg.mostDamage.toInt()} hasar")                } else {                    PacketEventBus.currentSession?.let {                        logFail(it, "Atlandı (anlık) - kendi hasarım yüksek (${dmg.selfDamage.toInt()} > ${dmg.mostDamage.toInt()})")                    }                }            }            is LevelEventPacket -> {                if (removeParticles.value && pkt.type == LevelEvent.PARTICLE_EXPLOSION) event.cancel()            }            else -> {}        }    }    // ── Tick loop ─────────────────────────────────────────────────────────    private suspend fun tickLoop() {        while (currentCoroutineContext().isActive) {            if (isEnabled) tick()            delay(TICK_INTERVAL_MS)        }    }    private fun tick() {        val session = PacketEventBus.currentSession ?: return        val now = System.currentTimeMillis()        if (now - lastExplodeMs >= explodeDelayMs.value) tryExplodeBest(session, now)        if (place.value && now - lastPlaceMs >= placeDelayMs.value) tryPlaceBest(session, now)    }    // ── Explode ───────────────────────────────────────────────────────────    private fun tryExplodeBest(session: RubidiumRelaySession, now: Long) {        val crystals = EntityTracker.getCrystals(range.value)        if (crystals.isEmpty()) return        var bestId: Long? = null        var bestDamage = -1f        for (c in crystals) {            val dmg = simulateExplosionDamage(c.x, c.y, c.z)            val effective = if (dmg.selfDamage > dmg.mostDamage && !suicide.value) -1f else dmg.mostDamage            if (effective > bestDamage) { bestDamage = effective; bestId = c.runtimeId }        }        if (bestId != null && bestDamage > 0f) {            explodeCrystal(session, bestId)            lastExplodeMs = now            sendLog(session, "Patlatıldı - ${bestDamage.toInt()} hasar")        } else {            logFail(session, "${crystals.size} kristal görünüyor ama hiçbiri güvenli/hasarlı değil")        }    }    // ── Multi-place ───────────────────────────────────────────────────────    //    // prepareItemForUse() bir kez çağrılır, N placement paketi aynı prepared    // item ile gönderilir, hotbar bir kez geri alınır (PlacementUtil.revert).    private fun tryPlaceBest(session: RubidiumRelaySession, now: Long) {        val bases = searchPlaceBase().toMutableList()        // Obsidian/bedrock yoksa rakip etrafındaki fallback pozisyonlar        if (bases.isEmpty()) {            for (target in EntityTracker.getPlayers(range.value)) {                if (target.runtimeId == EntityTracker.selfRuntimeId) continue                val tx = floor(target.x).toInt()                val ty = floor(target.y).toInt() - 1                val tz = floor(target.z).toInt()                for ((dx, dz) in listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0, 1 to 1, 1 to -1, -1 to 1, -1 to -1)) {                    bases.add(Triple(tx + dx, ty, tz + dz))                }            }        }        if (bases.isEmpty()) return        // Tüm pozisyonları hasar skoruna göre sırala, en iyi placeCount tanesini al        val topPositions = bases            .mapNotNull { pos ->                val cx = pos.first + 0.5f                val cy = pos.second + 2f                val cz = pos.third + 0.5f                val dmg = simulateExplosionDamage(cx, cy, cz)                val eff = if (dmg.selfDamage > dmg.mostDamage && !suicide.value) -1f else dmg.mostDamage                if (eff >= 0f || suicide.value) Pair(pos, eff) else null            }            .sortedByDescending { it.second }            .take(placeCount.value)        val finalPositions = if (topPositions.isNotEmpty()) topPositions        else bases.take(placeCount.value).map { Pair(it, 0f) }        if (finalPositions.isEmpty()) return        // Kristal slot'unu bir kez hazırla (PlacementUtil — doğru NbtBlockDefinition        // desteğine sahip, hem inventory'de hem hotbar'da arar, gerekirse taşır)        val prepared = PlacementUtil.prepareItemForUse(session, CRYSTAL_ID) ?: run {            logFail(session, "Envanterde kristal bulunamadı")            return        }        var placed = 0        for ((pos, _) in finalPositions) {            val blockPos = Vector3i.from(pos.first, pos.second, pos.third)            val blockId = WorldBlockTracker.getBlockIdentifier(pos.first, pos.second, pos.third) ?: "minecraft:obsidian"            val ok = PlacementUtil.sendPlacementUseRaw(                session   = session,                prepared  = prepared,                blockPos  = blockPos,                blockId   = blockId,                blockFace = 1            )            if (ok) placed++        }        PlacementUtil.revert(session, prepared)        if (placed > 0) {            lastPlaceMs = now            sendLog(session, "$placed kristal yerleştirildi")        } else {            logFail(session, "Yerleştirme başarısız (${finalPositions.size} pozisyon denendi, 0 başarılı)")        }    }    // ── Vanilla patlama hasarı simülasyonu ────────────────────────────────    private fun simulateExplosionDamage(cx: Float, cy: Float, cz: Float): ExplosionResult {        val diameter = EXPLOSION_SIZE * 2f        var selfDamage = 0f        var mostDamage = 0f        val selfDist = MathUtil.dist3(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY + 0.9f, EntityTracker.selfZ)        if (selfDist <= diameter) {            val exposure = exposureTo(cx, cy, cz, EntityTracker.selfX, EntityTracker.selfY, EntityTracker.selfZ)            selfDamage = explosionDamage(selfDist, diameter, exposure)        }        for (p in EntityTracker.getPlayers(diameter)) {            if (p.runtimeId == EntityTracker.selfRuntimeId) continue            val dist = MathUtil.dist3(cx, cy, cz, p.x, p.y + 0.9f, p.z)            if (dist > diameter) continue            val exposure = exposureTo(cx, cy, cz, p.x, p.y, p.z)            val dmg = explosionDamage(dist, diameter, exposure)            if (dmg > mostDamage) mostDamage = dmg        }        return ExplosionResult(mostDamage, selfDamage)    }    // Vanilla: impact = (1 - mesafe/çap) × exposure    //          hasar = (impact² + impact) / 2 × 7 × çap + 1    private fun explosionDamage(distance: Float, diameter: Float, exposure: Float): Float {        if (distance > diameter) return 0f        val impact = (1f - distance / diameter) * exposure        return (impact * impact + impact) / 2f * 7f * diameter + 1f    }    // 5 sample nokta → ray cast → blok engeli → exposure oranı    private fun exposureTo(cx: Float, cy: Float, cz: Float, tx: Float, ty: Float, tz: Float): Float {        if (!WorldBlockTracker.hasAnyTerrainData()) return 1f        val samples = arrayOf(            Triple(tx, ty + 0.1f, tz),            Triple(tx, ty + 0.9f, tz),            Triple(tx, ty + 1.6f, tz),            Triple(tx + 0.3f, ty + 0.9f, tz),            Triple(tx - 0.3f, ty + 0.9f, tz)        )        var clear = 0        for ((sx, sy, sz) in samples) {            if (!isRayBlocked(cx, cy, cz, sx, sy, sz)) clear++        }        return clear.toFloat() / samples.size    }    private fun isRayBlocked(x0: Float, y0: Float, z0: Float, x1: Float, y1: Float, z1: Float): Boolean {        val dist = MathUtil.dist3(x0, y0, z0, x1, y1, z1)        if (dist < 0.01f) return false        val steps = (dist * 2f).toInt().coerceIn(1, 40)        for (i in 1 until steps) {            val t = i.toFloat() / steps            val bx = floor(x0 + (x1 - x0) * t).toInt()            val by = floor(y0 + (y1 - y0) * t).toInt()            val bz = floor(z0 + (z1 - z0) * t).toInt()            val id = WorldBlockTracker.getBlockIdentifier(bx, by, bz) ?: continue            if (id !in NON_SOLID) return true        }        return false    }    // Menzil küpünde obsidian/bedrock + üstü boş olan zeminleri tara    private fun searchPlaceBase(): List<Triple<Int, Int, Int>> {        if (!WorldBlockTracker.hasAnyTerrainData()) return emptyList()        val r  = floor(range.value).toInt()        val cx = floor(EntityTracker.selfX).toInt()        val cy = floor(EntityTracker.selfY).toInt()        val cz = floor(EntityTracker.selfZ).toInt()        val bases = ArrayList<Triple<Int, Int, Int>>()        for (x in cx - r..cx + r) {            for (y in cy - r..cy + r) {                for (z in cz - r..cz + r) {                    val id = WorldBlockTracker.getBlockIdentifier(x, y, z) ?: continue                    if (id != "minecraft:obsidian" && id != "minecraft:bedrock") continue                    val above = WorldBlockTracker.getBlockIdentifier(x, y + 1, z)                    if (above != null && above !in NON_SOLID) continue                    bases.add(Triple(x, y, z))                }            }        }        return bases    }    // ── Paket göndericiler ────────────────────────────────────────────────    private fun explodeCrystal(session: RubidiumRelaySession, runtimeId: Long) {        PacketUtil.sendSwing(session)        PacketUtil.sendAttack(session, runtimeId)    }    // ── Log ──────────────────────────────────────────────────────────────    //    // sendToClient kullanılıyor (sendToServer DEĞİL) — bu paket gerçek    // sunucuya hiç gitmiyor, relay'in kendisi tarafından client'a enjekte    // ediliyor. Yani mesajı sadece sen görürsün, sunucu ve diğer oyuncular    // hiçbir şey almaz. TextPacket.Type.RAW isim/prefix eklemeden düz metin    // basar, normal chat mesajlarından ayırt edilebilir olsun diye.    private fun sendLog(session: RubidiumRelaySession, message: String) {        if (!log.value) return        try {            session.sendToClient(TextPacket().apply {                type               = TextPacket.Type.RAW                isNeedsTranslation = false                sourceName         = ""                xuid               = ""                platformChatId     = ""                setMessage("§b[CrystalAura]§f $message")                setFilteredMessage("")            })        } catch (_: Exception) {}    }    // Başarısızlık/atlama logları tick başına tekrar tekrar tetiklenebileceği    // için (örn. "envanterde kristal yok" her tick doğru kalır) ayrı bir    // throttle kullanılıyor — sendLog'daki başarı mesajları zaten olay    // bazlı olduğundan (yerleşme/patlama anında) throttle gerektirmiyor.    private fun logFail(session: RubidiumRelaySession, message: String) {        if (!log.value) return        val now = System.currentTimeMillis()        if (now - lastFailLogMs < LOG_FAIL_INTERVAL_MS) return        lastFailLogMs = now        sendLog(session, "⚠ $message")    }}